<?php
declare(strict_types=1);require_once __DIR__.'/../includes/admin.php';require_role(['super_admin','admin']);$pdo=db();$id=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT * FROM custom_forms WHERE id=?');$st->execute([$id]);$form=$st->fetch();if(!$form){http_response_code(404);exit('Form not found.');}$fields=json_decode($form['fields'],true)?:[];$st=$pdo->prepare('SELECT * FROM custom_form_submissions WHERE form_id=? ORDER BY created_at DESC');$st->execute([$id]);$rows=$st->fetchAll();admin_page('Form Submissions','forms','Responses for '.$form['title']);admin_flash();?><div class="admin-panel"><div class="registration-admin-toolbar"><div><strong><?=count($rows)?></strong><span>submissions</span></div><a class="btn outline" href="forms.php">← Form Builder</a></div><div class="admin-table-wrap"><table class="admin-table"><tr><th>#</th><?php foreach($fields as $f):?><th><?=e($f['label']??$f['name'])?></th><?php endforeach;?><th>Date</th></tr><?php foreach($rows as $r):$vals=json_decode($r['values_json'],true)?:[];$files=json_decode($r['uploaded_files']??'',true)?:[];?><tr><td><?=$r['id']?></td><?php foreach($fields as $f):$n=$f['name']??'';?><td><?=e((string)($vals[$n]??''))?><?php if(isset($files[$n])):?><br><a class="text-link" target="_blank" href="../<?=e($files[$n])?>">View file ↗</a><?php endif;?></td><?php endforeach;?><td><?=e($r['created_at'])?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="<?=count($fields)+2?>">No submissions yet.</td></tr><?php endif;?></table></div></div><?php admin_end();
